  ci_admin?: Prisma.ci_adminOmit
  ci_admin_roles?: Prisma.ci_admin_rolesOmit
  ci_email_templates?: Prisma.ci_email_templatesOmit
  ci_general_settings?: Prisma.ci_general_settingsOmit
  ci_language?: Prisma.ci_languageOmit
  dg_pics?: Prisma.dg_picsOmit
  module_access_old?: Prisma.module_access_oldOmit
  pam_activity_log?: Prisma.pam_activity_logOmit
  pam_activity_status?: Prisma.pam_activity_statusOmit
  pam_category?: Prisma.pam_categoryOmit
  pam_cities?: Prisma.pam_citiesOmit
  pam_countries?: Prisma.pam_countriesOmit
  pam_credit?: Prisma.pam_creditOmit
  pam_faq?: Prisma.pam_faqOmit
  pam_module?: Prisma.pam_moduleOmit
  pam_module_access?: Prisma.pam_module_accessOmit
  pam_photo_tags?: Prisma.pam_photo_tagsOmit
  pam_photos?: Prisma.pam_photosOmit
  pam_photos_files?: Prisma.pam_photos_filesOmit
  pam_states?: Prisma.pam_statesOmit
  pam_sub_category?: Prisma.pam_sub_categoryOmit
